# Surah Al-Anfal (chapter 8) — part 4: ayat 29-38 (IDs 1189-1198)
SURAH = 8

ENTRIES = {
1189: (
"اے ایمان والو — اگر — تم — اللہ سے — ڈرو — وہ — تمہارے لیے — فرقان — بنا دے گا — اور — تمہاری — خطاؤں — کو — دور کر دے گا — اور — تمہیں بخش دے گا — اور — اللہ — بڑے فضل — والا ہے",
"""۱۔ تقویٰ — فرقان (حق و باطل کی تمیز) کا سبب۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا إِن تَتَّقُوا اللَّهَ يَجْعَل لَّكُمْ فُرْقَانًا وَيُكَفِّرْ عَنكُمْ سَيِّئَاتِكُمْ وَيَغْفِرْ لَكُمْ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ‘‘ — اے ایمان والو — اگر — تم — اللہ سے — ڈرو — وہ — تمہارے لیے — فرقان — بنا دے گا — اور — تمہاری — خطاؤں — کو — دور کر دے گا — اور — تمہیں بخش دے گا — اور — اللہ — بڑے فضل — والا ہے — یعنی تقویٰ — حق و باطل کی — تمیز — کی صلاحیت — اور بخشش — کا وسیلہ ہے۔
۳۔ عملی سبق: تقویٰ اپناؤ؛ فرقان ملے گا۔"""
),
1190: (
"اور — یاد کرو — جب — وہ لوگ — جنہوں نے کفر کیا — آپؐ کے — خلاف — چال چل رہے تھے — کہ — آپ کو — قید کریں — یا — آپ کو قتل کریں — یا — آپ کو نکال دیں — اور اگر وہ — چال چلتے ہیں — اللہ بھی — چال چلتا ہے — اور — اللہ — بہترین — چال چلنے والا ہے",
"""۱۔ ہجرت سے پہلے — مکہ میں — رسولؐ کے خلاف — سازش۔
۲۔ ’’وَإِذْ يَمْكُرُ بِكَ الَّذِينَ كَفَرُوا لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ وَيَمْكُرُونَ وَيَمْكُرُ اللَّهُ وَاللَّهُ خَيْرُ الْمَاكِرِينَ‘‘ — اور — یاد کرو — جب — وہ لوگ — جنہوں نے کفر کیا — آپؐ کے — خلاف — چال چل رہے تھے — کہ — آپ کو — قید کریں — یا — آپ کو قتل کریں — یا — آپ کو نکال دیں — اور اگر وہ — چال چلتے ہیں — اللہ بھی — چال چلتا ہے — اور — اللہ — بہترین — چال چلنے والا ہے — یعنی دارالندوہ میں — کافروں کا منصوبہ — اور اللہ کی — حکمت — فن سبقت۔
۳۔ عملی سبق: اللہ کی تدبیریں — ہر چال پر — غالب ہیں۔"""
),
1191: (
"اور — جب — ہماری آیات — ان پر — پڑھی جائیں — تو کہتے ہیں — ہم نے — سن لیا — اگر ہم چاہیں — تو ہم بھی — ایسی — بات — کہہ دیں — یہ — نہیں ہے مگر — سابقین کی کہانیاں",
"""۱۔ کفار — قرآن کو افسانے کہتے ہیں۔
۲۔ ’’وَإِذَا تُتْلَىٰ عَلَيْهِمْ آيَاتُنَا قَالُوا قَدْ سَمِعْنَا لَوْ نَشَاءُ لَقُلْنَا مِثْلَ هَٰذَا إِنْ هَٰذَا إِلَّا أَسَاطِيرُ الْأَوَّلِينَ‘‘ — اور — جب — ہماری آیات — ان پر — پڑھی جائیں — تو کہتے ہیں — ہم نے — سن لیا — اگر ہم چاہیں — تو ہم بھی — ایسی — بات — کہہ دیں — یہ — نہیں ہے مگر — سابقین کی کہانیاں — یعنی کفار — قرآن کو — افسانے کہتے ہیں — جبکہ — وہ — قرآن جیسی کتاب — لا نہیں سکتے۔
۳۔ عملی سبق: قرآن — سابقین کی کہانیاں نہیں؛ اللہ کی وحی ہے۔"""
),
1192: (
"اور — جب انہوں نے کہا — اے اللہ — اگر — یہ — تیری طرف سے — حق ہے — تو — ہم پر — آسمان سے — پتھر — برسا — یا — کوئی دردناک عذاب — لا دے",
"""۱۔ کفار — چیلنج کرتے ہیں۔
۲۔ ’’وَإِذْ قَالُوا اللَّهُمَّ إِن كَانَ هَٰذَا هُوَ الْحَقَّ مِنْ عِندِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَۃً مِّنَ السَّمَاءِ أَوِ ائْتِنَا بِعَذَابٍ أَلِيمٍ‘‘ — اور — جب انہوں نے کہا — اے اللہ — اگر — یہ — تیری طرف سے — حق ہے — تو — ہم پر — آسمان سے — پتھر — برسا — یا — کوئی دردناک عذاب — لا دے — یعنی کفار — مغرور تھے — عذاب کا مطالبہ کرتے تھے۔
۳۔ عملی سبق: حق کو چیلنج کرنے کی بجائے — تسلیم کرو۔"""
),
1193: (
"اور — اللہ — نے — انہیں — اس وقت عذاب — دینے والا نہیں جب کہ — آپ — ان کے درمیان — موجود ہوں — اور — نہ — اللہ — انہیں — اس وقت — عذاب دے گا — جب کہ — وہ — استغفار کر رہے ہوں",
"""۱۔ رسولؐ کی موجودگی — اور استغفار — عذاب کو روکتے ہیں۔
۲۔ ’’وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ وَمَا كَانَ اللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ‘‘ — اور — اللہ — نے — انہیں — اس وقت عذاب — دینے والا نہیں جب کہ — آپ — ان کے درمیان — موجود ہوں — اور — نہ — اللہ — انہیں — اس وقت — عذاب دے گا — جب کہ — وہ — استغفار کر رہے ہوں — یعنی رسولؐ کی موجودگی اور — استغفار — دونوں — اللہ کے عذاب سے — حفاظت کرتے ہیں۔
۳۔ عملی سبق: استغفار — عذاب سے — بچاؤ کا سب سے بڑا — ہتھیار ہے۔"""
),
1194: (
"اور — کیا وجہ ہے — کہ — اللہ — انہیں عذاب — نہ دے — حالانکہ — وہ — مسجد الحرام سے — روک رہے ہیں — اور — وہ — اس کے — ولایت دار — نہیں — اس — کے ولایت دار — صرف — متقی ہیں — لیکن — ان — میں سے اکثر — نہیں جانتے",
"""۱۔ مسجد الحرام کے نگینہ دار — صرف متقی۔
۲۔ ’’وَمَا لَهُمْ أَلَّا يُعَذِّبَهُمُ اللَّهُ وَهُمْ يَصُدُّونَ عَنِ الْمَسْجِدِ الْحَرَامِ وَمَا كَانُوا أَوْلِيَاءَهُ إِنْ أَوْلِيَاؤُهُ إِلَّا الْمُتَّقُونَ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ‘‘ — اور — کیا وجہ ہے — کہ — اللہ — انہیں عذاب — نہ دے — حالانکہ — وہ — مسجد الحرام سے — روک رہے ہیں — اور — وہ — اس کے — ولایت دار — نہیں — اس — کے ولایت دار — صرف — متقی ہیں — لیکن — ان — میں سے اکثر — نہیں جانتے — یعنی مسجد الحرام — کا نگینہ — متقیوں کا حق ہے — مشرکوں کا — نہیں۔
۳۔ عملی سبق: مسجد الحرام کی تعظیم — متقیوں کا حق ہے؛ بیداری رکھو۔"""
),
1195: (
"اور — ان کی — بیت اللہ کے پاس — نماز — نہیں ہے مگر — سیٹی بجانا اور — تالیاں بجانا — پس — عذاب — چکھو — اس — کفر کی وجہ سے جو — تم کرتے تھے",
"""۱۔ مشرکوں کی — بیت اللہ کے پاس — عبادت — ناچ گانا۔
۲۔ ’’وَمَا كَانَ صَلَاتُهُمْ عِندَ الْبَيْتِ إِلَّا مُكَاءً وَتَصْدِيَۃً فَذُوقُوا الْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ‘‘ — اور — ان کی — بیت اللہ کے پاس — نماز — نہیں ہے مگر — سیٹی بجانا اور — تالیاں بجانا — پس — عذاب — چکھو — اس — کفر کی وجہ سے جو — تم کرتے تھے — یعنی مشرکین — بیت اللہ کو — کھیل کود کا مرکز — بنا چکے تھے۔
۳۔ عملی سبق: عبادت — اخلاص کے ساتھ — کی جائے؛ رسم و رواج میں — نہیں۔"""
),
1196: (
"بے شک — جو — کفر کرتے ہیں — وہ — اپنے مال — خرچ کر رہے ہیں — تاکہ — اللہ کے راستے سے — روکیں — عنقریب — وہ — اسے خرچ کریں گے — پھر — وہ — ان — کے لیے — حسرت — بنے گی — پھر — وہ — مغلوب ہو جائیں گے — اور — جنہوں نے — کفر کیا — انہیں — جہنم — کی طرف — اکٹھا کیا جائے گا",
"""۱۔ کفار — اللہ کی راہ روکنے کے لیے مال خرچ کرتے ہیں — مگر ناکام ہوتے ہیں۔
۲۔ ’’إِنَّ الَّذِينَ كَفَرُوا يُنفِقُونَ أَمْوَالَهُمْ لِيَصُدُّوا عَن سَبِيلِ اللَّهِ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَۃً ثُمَّ يُغْلَبُونَ وَالَّذِينَ كَفَرُوا إِلَىٰ جَهَنَّمَ يُحْشَرُونَ‘‘ — بے شک — جو — کفر کرتے ہیں — وہ — اپنے مال — خرچ کر رہے ہیں — تاکہ — اللہ کے راستے سے — روکیں — عنقریب — وہ — اسے خرچ کریں گے — پھر — وہ — ان — کے لیے — حسرت — بنے گی — پھر — وہ — مغلوب ہو جائیں گے — اور — جنہوں نے — کفر کیا — انہیں — جہنم — کی طرف — اکٹھا کیا جائے گا — یعنی کفار کا — اللہ کی راہ روکنے کا منصوبہ — ناکام — اور آخرت میں — جہنم — ان کا انجام ہوگا۔
۳۔ عملی سبق: اللہ کی راہ روکنے کا — کوئی بھی منصوبہ — کامیاب نہیں ہوگا۔"""
),
1197: (
"تاکہ — اللہ — پلید کو — پاکیزہ سے — الگ کرے — اور — پلید کو — ایک دوسرے پر — ڈالے — پس — اسے — سب — جمع کرے — پھر — اسے — جہنم — میں — ڈال دے — یہی لوگ — نقصان — پانے والے ہیں",
"""۱۔ اللہ — حق و باطل — کو الگ کرتا ہے۔
۲۔ ’’لِّيَمِيزَ اللَّهُ الْخَبِيثَ مِنَ الطَّيِّبِ وَيَجْعَلَ الْخَبِيثَ بَعْضَهُ عَلَىٰ بَعْضٍ فَيَرْكُمَهُ جَمِيعًا فَيَجْعَلَهُ فِي جَهَنَّمَ أُولَٰئِكَ هُمُ الْخَاسِرُونَ‘‘ — تاکہ — اللہ — پلید کو — پاکیزہ سے — الگ کرے — اور — پلید کو — ایک دوسرے پر — ڈالے — پس — اسے — سب — جمع کرے — پھر — اسے — جہنم — میں — ڈال دے — یہی لوگ — نقصان — پانے والے ہیں — یعنی اللہ — حق اور باطل — دونوں کو — نمایاں کر کے — باطل کو — جہنم میں — ڈالتا ہے۔
۳۔ عملی سبق: اللہ — حق و باطل کو — الگ کر کے دکھا دیتا ہے۔"""
),
1198: (
"کہدو — جنہوں نے — کفر کیا — اگر — وہ — باز آ جائیں — تو — جو کچھ — گزر چکا — انہیں — بخش دیا جائے گا — اور — اگر — وہ — واپس لوٹے — تو — گزشتہ اقوام کی — سنت — گزر چکی",
"""۱۔ توبہ — ہر وقت — ممکن ہے۔
۲۔ ’’قُل لِّلَّذِينَ كَفَرُوا إِن يَنتَهُوا يُغْفَرْ لَهُم مَّا قَدْ سَلَفَ وَإِن يَعُودُوا فَقَدْ مَضَتْ سُنَّۃُ الْأَوَّلِينَ‘‘ — کہدو — جنہوں نے — کفر کیا — اگر — وہ — باز آ جائیں — تو — جو کچھ — گزر چکا — انہیں — بخش دیا جائے گا — اور — اگر — وہ — واپس لوٹے — تو — گزشتہ اقوام کی — سنت — گزر چکی — یعنی توبہ — ہر وقت — دستیاب ہے؛ پرانے کفر کی — معافی — ہو سکتی ہے۔
۳۔ عملی سبق: توبہ — کبھی دیر سے — نہیں ہوتی؛ ابھی کر لو۔"""
),
}
